import{_ as p,a0 as r,w as s,s as l,ao as u,I as a,x as n,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const g=JSON.parse('{"title":"Linux 有問必答：如何在Ubuntu或者Debian中啓動後進入命令列 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有問必答：如何在Ubuntu或者Debian中啓動後進入命令列 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有問必答：如何在Ubuntu或者Debian中啓動後進入命令列 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有問必答：如何在Ubuntu或者Debian中啓動後進入命令列 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20150121 Linux FAQs with Answers--How to boot into command line on Ubuntu or Debian","title":"Linux 有問必答：如何在Ubuntu或者Debian中啓動後進入命令列","tag":"201501","desc":""},"relativePath":"201501/20150121 Linux FAQs with Answers--How to boot into command line on Ubuntu or Debian.md","filePath":"[post].md"}'),b={name:"201501/20150121 Linux FAQs with Answers--How to boot into command line on Ubuntu or Debian.md"};function m(d,t,_,f,x,U){const o=r("Link");return s(),l("div",null,[t[14]||(t[14]=u('<h1 id="linux-有問必答-如何在ubuntu或者debian中啓動後進入命令列" tabindex="-1">Linux 有問必答：如何在Ubuntu或者Debian中啓動後進入命令列 <a class="header-anchor" href="#linux-有問必答-如何在ubuntu或者debian中啓動後進入命令列" aria-label="Permalink to “Linux 有問必答：如何在Ubuntu或者Debian中啓動後進入命令列”">​</a></h1><blockquote><p><strong>提問</strong>：我運行的是Ubuntu桌面，但是我希望啓動後臨時進入命令列。有什麼簡便的方法可以啓動進入終端？</p></blockquote><p>Linux桌面自帶了一個顯示管理器（比如：GDM、KDM、LightDM），它們可以讓計算機啓動自動進入一個基於GUI的登錄環境。然而，如果你要直接啓動進入終端怎麼辦？ 比如，你在排查桌面相關的問題或者想要運行一個不需要GUI的應用程序。</p><p>注意雖然你可以通過按下Ctrl+Alt+F1到F6臨時從桌面GUI切換到虛擬終端。然而，在這種情況下你的桌面GUI仍在後台運行，這不同於純文本模式啓動。</p><p>在Ubuntu或者Debian桌面中，你可以通過傳遞合適的內核參數在啓動時啓動文本模式。</p><h3 id="啓動臨時進入命令列" tabindex="-1">啓動臨時進入命令列 <a class="header-anchor" href="#啓動臨時進入命令列" aria-label="Permalink to “啓動臨時進入命令列”">​</a></h3><p>如果你想要禁止桌面GUI並臨時進入一次文本模式，你可以使用GRUB菜單。</p><p>首先，打開你的電腦。當你看到初始的GRUB菜單時，按下‘e’。</p><p><img src="https://farm8.staticflickr.com/7490/16112246542_bc1875a397_z.jpg" alt=""></p><p>接着會進入下一屏，這裏你可以修改內核啓動選項。向下滾動到以“linux”開始的行，這裏就是內核參數的列表。刪除參數列表中的“quiet”和“splash”。在參數列表中添加“text”。</p><p><img src="https://farm8.staticflickr.com/7471/15493282603_8a70f70af2_z.jpg" alt=""></p><p>升級的內核選項列表看上去像這樣。按下Ctrl+x繼續啓動。這會以詳細模式啓動控制台一次（LCTT譯註：由於沒有保存修改，所以下次重啓還會進入 GUI）。</p><p><img src="https://farm8.staticflickr.com/7570/15925676530_b11af59243_z.jpg" alt=""></p><h3 id="永久啓動進入命令列" tabindex="-1">永久啓動進入命令列 <a class="header-anchor" href="#永久啓動進入命令列" aria-label="Permalink to “永久啓動進入命令列”">​</a></h3>',14)),a("p",null,[t[1]||(t[1]=n("如果你想要永久啓動進入命令列，你需要",-1)),e(o,{href:"http://xmodulo.com/add-kernel-boot-parameters-via-grub-linux.html"},{default:i(()=>[...t[0]||(t[0]=[n("更新定義了內核啓動參數GRUB設置",-1)])]),_:1}),t[2]||(t[2]=n("。",-1))]),t[15]||(t[15]=u(`<p>在文本編輯器中打開默認的GRUB配置文件。</p><pre><code>$ sudo vi /etc/default/grub 
</code></pre><p>查找以GRUB_CMDLINE_LINUX_DEFAULT開頭的行，並用“#”註釋這行。這會禁止初始屏幕，而啓動詳細模式（也就是説顯示詳細的的啓動過程）。</p><p>更改GRUB_CMDLINE_LINUX=&quot;&quot; 成：</p><pre><code>GRUB_CMDLINE_LINUX=&quot;text&quot;
</code></pre><p>接下來取消“#GRUB_TERMINAL=console”的註釋。</p><p>更新後的GRUB配置看上去像下面這樣。</p><p><img src="https://farm9.staticflickr.com/8673/16107564442_9345d94491_b.jpg" alt=""></p><p>最後，使用update-grub命令來基於這些更改重新生成/boot下的GRUB2配置文件。</p><pre><code>$ sudo update-grub 
</code></pre><p>這時，你的桌面應該可以從GUI啓動切換到控制台啓動了。可以通過重啓驗證。</p><p><img src="https://farm8.staticflickr.com/7518/16106378151_81ac6b5a49_b.jpg" alt=""></p><hr>`,13)),a("p",null,[t[4]||(t[4]=n("via: ",-1)),e(o,{href:"http://ask.xmodulo.com/boot-into-command-line-ubuntu-debian.html"},{default:i(()=>[...t[3]||(t[3]=[n("http://ask.xmodulo.com/boot-into-command-line-ubuntu-debian.html",-1)])]),_:1})]),a("p",null,[t[7]||(t[7]=n("譯者：",-1)),e(o,{href:"https://github.com/geekpi"},{default:i(()=>[...t[5]||(t[5]=[n("geekpi",-1)])]),_:1}),t[8]||(t[8]=n(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[6]||(t[6]=[n("wxy",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=n("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[9]||(t[9]=[n("LCTT",-1)])]),_:1}),t[12]||(t[12]=n(" 原創翻譯，",-1)),e(o,{href:"http://linux.cn/"},{default:i(()=>[...t[10]||(t[10]=[n("Linux中國",-1)])]),_:1}),t[13]||(t[13]=n(" 榮譽推出",-1))])])}const D=p(b,[["render",m]]);export{g as __pageData,D as default};
